// Event types
type OrderEvent =
  | { type: 'OrderPlaced';  orderId: string; items: Item[] }
  | { type: 'ItemAdded';    item: Item }
  | { type: 'OrderShipped'; trackingNumber: string }
  | { type: 'OrderCancelled'; reason: string };

// Aggregate state
type OrderState = {
  id: string;
  items: Item[];
  status: 'pending' | 'shipped' | 'cancelled';
  trackingNumber?: string;
};

// Apply function — pure, no side effects
function apply(state: OrderState, event: OrderEvent): OrderState {
  switch (event.type) {
    case 'OrderPlaced':
      return { id: event.orderId, items: event.items, status: 'pending' };
    case 'ItemAdded':
      return { ...state, items: [...state.items, event.item] };
    case 'OrderShipped':
      return { ...state, status: 'shipped', trackingNumber: event.trackingNumber };
    case 'OrderCancelled':
      return { ...state, status: 'cancelled' };
  }
}

// Rebuild state by folding over event log
function rehydrate(events: OrderEvent[]): OrderState {
  return events.reduce(apply, {} as OrderState);
}

// Without upcasting — messy apply function
function apply(state: State, event: AnyEvent): State {
  if (event.type === 'CustomerRegistered') {
    // v1: had 'name' field
    // v2: split into 'firstName' + 'lastName'
    const firstName = (event as any).firstName ?? (event as any).name?.split(' ')[0];
    const lastName  = (event as any).lastName  ?? (event as any).name?.split(' ')[1];
    return { ...state, firstName, lastName };
  }
  // ... more version-specific branches
}

// Upcaster registry
const upcasters: Record<string, (raw: any) => any> = {
  'CustomerRegistered@v1': (e) => ({
    ...e,
    type: 'CustomerRegistered',
    version: 2,
    firstName: e.name?.split(' ')[0] ?? '',
    lastName:  e.name?.split(' ')[1] ?? '',
    name: undefined,   // remove legacy field
  }),
};

function deserialize(raw: any): DomainEvent {
  const key = `${raw.type}@v${raw.version ?? 1}`;
  const upcast = upcasters[key];
  return upcast ? upcast(raw) : raw;
}

// apply function is now clean — always sees current schema
function apply(state: State, event: CustomerRegistered): State {
  return { ...state, firstName: event.firstName, lastName: event.lastName };
}
